    const storagePercentage = Math.min(Math.round(storageUsedBytes / R2_STORAGE_LIMIT * 1e3) / 10, 100);
    const d1Percentage = Math.min(Math.round(totalRequests / D1_MONTHLY_REQUESTS_LIMIT * 1e3) / 10, 100);
